<?php declare(strict_types=1); $stamp=strtotime($item['event_date']); $isPast=$item['event_date']<$today->format('Y-m-d'); ps_page_hero($isPast?ps_text('संपन्न कार्यक्रम','COMPLETED EVENT'):ps_text('आगामी कार्यक्रम','UPCOMING EVENT'),$item['title'],ps_excerpt($item)); ?>
<section class="ps-section"><div class="ps-container ps-detail-grid"><article class="ps-detail-main"><?php if(ps_image_path($item['image']??'')): ?><figure class="ps-detail-image"><?php ps_image($item['image'],$item['title'],'',true); ?></figure><?php endif; ?><span class="ps-eyebrow"><?= e(ps_text('कार्यक्रम विवरण','EVENT STORY')) ?></span><div class="ps-rich-text"><?= ps_rich_text($item['content']??'') ?></div></article><aside class="ps-detail-aside"><dl><div><dt><?= e(ps_text('दिनांक','Date')) ?></dt><dd><time datetime="<?= e($item['event_date']) ?>"><?= e(date('d M Y',$stamp)) ?></time></dd></div><?php if($item['location']): ?><div><dt><?= e(ps_text('स्थान','Location')) ?></dt><dd><?= e($item['location']) ?></dd></div><?php endif; ?><div><dt><?= e(ps_text('स्थिति','Status')) ?></dt><dd><?= e($isPast?ps_text('संपन्न','Completed'):ps_text('आगामी','Upcoming')) ?></dd></div></dl><a class="ps-button" href="<?= e(base_url('/contact')) ?>"><?= e(ps_text('जानकारी प्राप्त करें','Ask for information')) ?> ↗</a></aside></div></section>
<section class="ps-section ps-tint"><div class="ps-container"><?php ps_heading('related-events',ps_text('अन्य गतिविधियाँ','MORE FROM THE CALENDAR'),ps_text('अन्य कार्यक्रम','Related events.')); ?><div class="ps-event-groups"><div><?php foreach(array_slice(array_values(array_filter($events,fn($e)=>$e['slug']!==$item['slug'])),0,3) as $event): ?><article class="ps-event"><div><h3><a href="<?= e(base_url('/events/'.$event['slug'])) ?>"><?= e($event['title']) ?></a></h3><p><?= e(format_date($event['event_date'])) ?> · <?= e($event['location']??'') ?></p></div><a class="ps-event-arrow" href="<?= e(base_url('/events/'.$event['slug'])) ?>">↗</a></article><?php endforeach; ?></div></div></div></section>
<?php ps_cta(ps_text('समुदाय के साथ जुड़ें','Connect with the community.')); ?>
